//! The generated files, as text: the table in Rust, the table in the docs, the report of what was
//! left out, and the pin lines in THIRD-PARTY.md.

use std::collections::BTreeMap;

use crate::select::Left;
use crate::sources::{Format, Source};

/// One built-in, as the table publishes it.
pub struct Row {
    pub id: String,
    pub source: String,
    pub rule: String,
    pub pattern: String,
    pub changed: Option<String>,
}

pub const RUST_HEADER: &str = "\
// @generated by tools/secret-patterns from the lists its sources.toml pins and the changes in its
// changes.toml. Don't edit it: change those and rerun the tool. CI fails on any difference.
";

/// A Rust string literal for printable ASCII text.
fn rust_str(s: &str) -> Result<String, String> {
    let mut out = String::from("\"");
    for c in s.chars() {
        if !c.is_ascii() || c.is_ascii_control() {
            return Err(format!(
                "{s:?} isn't printable ASCII, which the table holds"
            ));
        }
        if c == '"' || c == '\\' {
            out.push('\\');
        }
        out.push(c);
    }
    Ok(out + "\"")
}

/// A Rust raw string literal with as few `#` as it needs.
fn rust_raw(s: &str) -> String {
    let mut h = String::from("#");
    while s.contains(&format!("\"{h}")) {
        h.push('#');
    }
    format!("r{h}\"{s}\"{h}")
}

pub fn rust(rows: &[Row], retired: &[(String, String)]) -> Result<String, String> {
    let mut out = String::from(RUST_HEADER);
    out += "\nuse super::Shape;\n\n";
    out += "/// Every built-in shape, by id. The selection rule is in the module's doc; `docs/config.md`\n";
    out += "/// lists them in the same order.\n";
    out += "pub const BUILTINS: &[Shape] = &[\n";
    for r in rows {
        out += "    Shape {\n";
        out += &format!("        id: {},\n", rust_str(&r.id)?);
        out += &format!("        source: {},\n", rust_str(&r.source)?);
        out += &format!("        rule: {},\n", rust_str(&r.rule)?);
        out += &format!("        pattern: {},\n", rust_raw(&r.pattern));
        match &r.changed {
            Some(c) => out += &format!("        changed: Some({}),\n", rust_str(c)?),
            None => out += "        changed: None,\n",
        }
        out += "    },\n";
    }
    out += "];\n\n";
    out += "/// Ids that named a built-in in an earlier release, each with the last release that had it.\n";
    out += "/// `disable` accepts them, and they turn nothing off.\n";
    if retired.is_empty() {
        out += "pub const RETIRED: &[(&str, &str)] = &[];\n";
    } else {
        out += "pub const RETIRED: &[(&str, &str)] = &[\n";
        for (id, last) in retired {
            out += &format!("    ({}, {}),\n", rust_str(id)?, rust_str(last)?);
        }
        out += "];\n";
    }
    Ok(out)
}

pub const DOCS_BEGIN: &str =
    "<!-- BEGIN generated by tools/secret-patterns: the built-in patterns. Don't edit. -->";
/// The end of every generated part of a hand-written file.
pub const END: &str = "<!-- END generated -->";

pub fn docs_table(rows: &[Row]) -> String {
    let cell = |s: &str| s.replace('|', "\\|");
    let mut out = String::from("| Id | Pattern | Source |\n|---|---|---|\n");
    for r in rows {
        let source = if r.source == "whimbrel" {
            format!("whimbrel's own: {}", r.rule)
        } else {
            let t = format!("{} `{}`", r.source, r.rule);
            match &r.changed {
                Some(c) => format!("{t}; {c}"),
                None => t,
            }
        };
        out += &format!(
            "| `{}` | `{}` | {} |\n",
            r.id,
            cell(&r.pattern),
            cell(&source)
        );
    }
    out
}

pub fn left_out(read: usize, picked: usize, left: &[Left]) -> String {
    let mut why: BTreeMap<&str, usize> = BTreeMap::new();
    for l in left {
        let key = if l.why.starts_with("already covered by ") {
            "already covered by a rule taken from an earlier list"
        } else {
            &l.why
        };
        *why.entry(key).or_default() += 1;
    }
    let mut why: Vec<_> = why.into_iter().collect();
    why.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    let mut out = String::from(
        "<!-- @generated by tools/secret-patterns. Don't edit it: rerun the tool. -->\n\n\
         # The rules the built-in secret patterns leave out\n\n\
         Every rule of the pinned lists that the selection rule in `src/secret_patterns.rs` leaves out,\n\
         and why, in the order the lists are read. A source bump shows up here as a diff.\n\n",
    );
    out += &format!(
        "The lists have {read} rules. The built-ins take {picked} and leave {}:\n\n",
        left.len()
    );
    for (w, n) in why {
        out += &format!("- {n}: {w}\n");
    }
    out += "\n| Source | Rule | Why |\n|---|---|---|\n";
    for l in left {
        out += &format!(
            "| {} | `{}` | {} |\n",
            l.source,
            l.rule,
            l.why.replace('|', "\\|")
        );
    }
    out
}

/// The pin line for one list in THIRD-PARTY.md.
pub fn pin(s: &Source) -> String {
    let at = match &s.tag {
        Some(tag) => format!("{tag} (commit `{}`)", s.commit),
        None => format!("commit `{}`", s.commit),
    };
    let kind = match s.format {
        Format::Toml => "blob",
        Format::Go => "tree",
    };
    format!(
        "{begin}\nAt {at}:\n<https://github.com/{}/{kind}/{}/{}>.\n{END}",
        s.repo,
        s.commit,
        s.read,
        begin = pin_begin(&s.name),
    )
}

pub fn pin_begin(name: &str) -> String {
    format!("<!-- BEGIN generated by tools/secret-patterns: the {name} pin. Don't edit. -->")
}

/// `text` with what's between `begin` and the next `end` replaced by `inner`, markers kept.
pub fn splice(text: &str, begin: &str, end: &str, inner: &str) -> Result<String, String> {
    let a = text
        .find(begin)
        .ok_or_else(|| format!("no marker {begin:?}"))?;
    let b = a + text[a..]
        .find(end)
        .ok_or_else(|| format!("no {end:?} after {begin:?}"))?;
    Ok(format!("{}{inner}{}", &text[..a], &text[b + end.len()..]))
}
